jobs:
  excavate:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: 22
      - name: Install dependencies without lockfile
        run: npm install --no-audit --no-fund
      - name: Regenerate every uncapped source finding
        run: |
          npm run vision:ingest
          npm run plans:ingest
      - name: Verify no finding was omitted from persisted reports
        run: |
          node <<'NODE'
          const fs=require('fs');
          for (const file of [
            'data/runtime-reports/latest-founder-vision-ingestion.json',
            'data/runtime-reports/latest-unfinished-plan-ingestion.json'
          ]) {
            const report=JSON.parse(fs.readFileSync(file,'utf8'));
            if (!Array.isArray(report.findings)) throw new Error(`missing findings array: ${file}`);
            if (report.findings.length !== report.totals.findings) {
              throw new Error(`truncated report ${file}: persisted=${report.findings.length}, counted=${report.totals.findings}`);
            }
            console.log(`${file}: counted=${report.totals.findings}, persisted=${report.findings.length}`);
          }
          NODE
      - name: Generate module-aware corpus
        run: npm run knowledge:excavate:v2
      - name: Marry screenshot learnings to every recovered record
        run: npm run knowledge:marry:screenshots
      - name: Archive every record by module and topic
        run: npm run knowledge:archive:semantic
      - name: Verify complete corpus, marriage and semantic archive
        shell: bash
        run: |
          test -f data/recovery/canonical-knowledge-v2/manifest.json
          test -f data/recovery/canonical-knowledge-v2/photo-marriage/crosswalk.json
          test -f data/recovery/canonical-knowledge-v2/semantic-archive/archive-manifest.json
          node <<'NODE'
          const fs=require('fs');
          const m=JSON.parse(fs.readFileSync('data/recovery/canonical-knowledge-v2/manifest.json','utf8'));
          const x=JSON.parse(fs.readFileSync('data/recovery/canonical-knowledge-v2/photo-marriage/crosswalk.json','utf8'));
          const a=JSON.parse(fs.readFileSync('data/recovery/canonical-knowledge-v2/semantic-archive/archive-manifest.json','utf8'));
          if(!(m.totalRecords>0)) throw new Error('empty corpus');
          if(!(m.totalBatches>0)) throw new Error('no batches');
          const required=['founder-vision','unfinished-gap','recovery','donor','current-code','live-state'];
          for(const family of required){ if(!(family in m.sourceCounts)) throw new Error(`missing source family ${family}`); }
          if(!m.moduleCounts || Object.keys(m.moduleCounts).length < 5) throw new Error('insufficient module distribution');
          if(!m.reviewCounts || !('REVIEW_REQUIRED' in m.reviewCounts || 'CLASSIFIED' in m.reviewCounts)) throw new Error('missing semantic review state');
          if(!m.truthRule) throw new Error('missing truth rule');

jobs:
  analyze:
    if: github.event.pull_request.head.repo.full_name == github.repository
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
        with:
          ref: ${{ github.head_ref }}
          fetch-depth: 0
      - name: Fetch main and exact snapshot refs
        run: |
          git fetch --no-tags origin '+refs/heads/main:refs/remotes/origin/main'
          git fetch --no-tags origin '+refs/heads/recovery/snapshots/*:refs/remotes/origin/recovery/snapshots/*'
      - name: Analyze every changed file in every snapshot
        run: node scripts/pantavion-deep-branch-analysis.cjs
      - name: Verify manifest truth state
        run: |
          node <<'NODE'
          const fs=require('fs');
          const m=JSON.parse(fs.readFileSync('data/recovery/deep-analysis/manifest.json','utf8'));
          if(m.totals.snapshotBranches !== 91) throw new Error('snapshot count mismatch');
          if(!m.stages.preserved || !m.stages.deeplyAnalyzedMachinePass) throw new Error('analysis stages missing');
          if(m.stages.canonicalized || m.stages.tested || m.stages.verified || m.stages.deleteAllowed) throw new Error('premature completion claim');
          if(m.branches.length !== 91) throw new Error('branch report count mismatch');
          for(const b of m.branches) {
            if(!fs.existsSync(b.report)) throw new Error('missing report '+b.report);
            const r=JSON.parse(fs.readFileSync(b.report,'utf8'));
            if(r.changedFileCount !== r.files.length) throw new Error('file count mismatch '+b.sourceRef);
          }
          console.log(JSON.stringify(m.totals));
          NODE
      - name: Commit transparent analysis reports
        run: |
          git config user.name 'pantavion-recovery-bot'
          git config user.email 'pantavion-recovery-bot@users.noreply.github.com'
          git add data/recovery/deep-analysis
          if git diff --cached --quiet; then
            echo 'Deep-analysis reports already current.'
            exit 0
          fi
          git commit -m 'data(recovery): deep-analyze all 91 snapshot branches'
          git push origin "HEAD:${{ github.head_ref }}"

